// Package mcpserver serves protobuf services as MCP tools with the text and
// behaviour declared in their raveesh_me.http_proto_lint.v1 options.
//
// Code generated by protoc-gen-go-mcp registers the tools. Wrap sits between
// that code and the official MCP Go SDK: it replaces each tool's comment-based
// description with the declared tool title and description, adds the MCP
// behaviour hints, and passes the caller's headers on. Forward the generated
// tools to a Connect client built with Client, so every MCP call runs through
// the same auth, scope checks, flow IDs and error audit as REST and RPC calls.
package mcpserver

import (
	"context"
	"encoding/json"
	"net/http"

	"github.com/modelcontextprotocol/go-sdk/mcp"
	"github.com/redpanda-data/protoc-gen-go-mcp/pkg/gen"
	"github.com/redpanda-data/protoc-gen-go-mcp/pkg/runtime"
	"google.golang.org/protobuf/proto"
	"google.golang.org/protobuf/reflect/protoreflect"
	"google.golang.org/protobuf/types/descriptorpb"

	hplv1 "github.com/raveesh-me/http-proto-lint/gen/go/raveesh_me/http_proto_lint/v1"
)

// forwardedHeaders are copied from the MCP request onto the forwarded call.
var forwardedHeaders = []string{"Authorization", "X-Flow-ID"}

type server struct {
	s       *mcp.Server
	methods map[string]protoreflect.MethodDescriptor // tool name to method
}

// Wrap returns a runtime.MCPServer that registers the tools of the services
// on s. Pass it to the generated ForwardToConnect<Service>Client functions.
func Wrap(s *mcp.Server, services ...protoreflect.ServiceDescriptor) runtime.MCPServer {
	methods := map[string]protoreflect.MethodDescriptor{}
	for _, svc := range services {
		for i := 0; i < svc.Methods().Len(); i++ {
			m := svc.Methods().Get(i)
			methods[gen.ToolForMethod(m, "").Name] = m
		}
	}
	return &server{s: s, methods: methods}
}

// AddTool implements runtime.MCPServer.
func (w *server) AddTool(tool runtime.Tool, handler runtime.ToolHandler) {
	w.s.AddTool(w.describe(tool), func(ctx context.Context, req *mcp.CallToolRequest) (*mcp.CallToolResult, error) {
		args := map[string]any{}
		if raw := req.Params.Arguments; len(raw) > 0 {
			if err := json.Unmarshal(raw, &args); err != nil {
				return nil, err
			}
		}
		if req.Extra != nil {
			ctx = withHeaders(ctx, req.Extra.Header)
		}
		result, err := handler(ctx, &runtime.CallToolRequest{Arguments: args})
		if err != nil || result == nil {
			return nil, err
		}
		return &mcp.CallToolResult{
			Content:           []mcp.Content{&mcp.TextContent{Text: result.Text}},
			StructuredContent: result.StructuredContent,
			IsError:           result.IsError,
		}, nil
	})
}

// describe builds the SDK tool from the declared options, falling back to
// what protoc-gen-go-mcp derived from comments.
func (w *server) describe(tool runtime.Tool) *mcp.Tool {
	out := &mcp.Tool{
		Name:        tool.Name,
		Description: tool.Description,
		InputSchema: json.RawMessage(tool.RawInputSchema),
	}
	if len(tool.RawOutputSchema) > 0 {
		out.OutputSchema = json.RawMessage(tool.RawOutputSchema)
	}
	m, ok := w.methods[tool.Name]
	if !ok {
		return out
	}
	rules, _ := proto.GetExtension(m.Options(), hplv1.E_Method).(*hplv1.MethodRules)
	if d := rules.GetTool().GetDescription(); d != "" {
		out.Description = d
	}
	out.Title = rules.GetTool().GetTitle()
	out.Annotations = annotations(m, rules)
	out.InputSchema = describeSchema(tool.RawInputSchema, m.Input())
	return out
}

// annotations derives the MCP behaviour hints from the contract: reads are
// NO_SIDE_EFFECTS methods, and destructive is declared on the tool.
func annotations(m protoreflect.MethodDescriptor, rules *hplv1.MethodRules) *mcp.ToolAnnotations {
	opts, _ := m.Options().(*descriptorpb.MethodOptions)
	level := opts.GetIdempotencyLevel()
	readOnly := level == descriptorpb.MethodOptions_NO_SIDE_EFFECTS
	destructive := rules.GetTool().GetDestructive()
	openWorld := false
	return &mcp.ToolAnnotations{
		Title:           rules.GetTool().GetTitle(),
		ReadOnlyHint:    readOnly,
		IdempotentHint:  readOnly || level == descriptorpb.MethodOptions_IDEMPOTENT,
		DestructiveHint: &destructive,
		OpenWorldHint:   &openWorld,
	}
}

// describeSchema sets the input schema's description from the request
// message's declared description.
func describeSchema(raw json.RawMessage, input protoreflect.MessageDescriptor) json.RawMessage {
	rules, _ := proto.GetExtension(input.Options(), hplv1.E_Message).(*hplv1.MessageRules)
	if rules.GetDescription() == "" {
		return raw
	}
	var schema map[string]any
	if err := json.Unmarshal(raw, &schema); err != nil {
		return raw
	}
	schema["description"] = rules.GetDescription()
	out, err := json.Marshal(schema)
	if err != nil {
		return raw
	}
	return out
}

type headersKey struct{}

func withHeaders(ctx context.Context, h http.Header) context.Context {
	kept := http.Header{}
	for _, name := range forwardedHeaders {
		if v := h.Get(name); v != "" {
			kept.Set(name, v)
		}
	}
	return context.WithValue(ctx, headersKey{}, kept)
}
